declare class TreeNode {
  val: number
  left: TreeNode | null
  right: TreeNode | null
  constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null)
}

function maxPathSum(root: TreeNode | null): number {
  let best = -Infinity
  function down(n: TreeNode | null): number {
    if (!n) return 0
    const left = Math.max(0, down(n.left))
    const right = Math.max(0, down(n.right))
    best = Math.max(best, n.val + left + right)
    return n.val + Math.max(left, right)
  }
  down(root)
  return best
}
